--
-- Estructura de tabla para la tabla `medios_generados`
--

CREATE TABLE `medios_generados` (
  `id_medio` int(11) NOT NULL,
  `id_mensaje` int(11) NOT NULL,
  `tipo` enum('imagen','audio','video') NOT NULL,
  `url` varchar(255) NOT NULL,
  `proveedor` varchar(50) DEFAULT NULL,
  `estado_moderacion` enum('pendiente','aprobado','rechazado') NOT NULL DEFAULT 'pendiente',
  `fecha_creacion` datetime DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `memoria_conversacion`
--

CREATE TABLE `memoria_conversacion` (
  `id_memoria` int(11) NOT NULL,
  `id_conversacion` int(11) NOT NULL,
  `resumen` text DEFAULT NULL,
  `ultimo_orden_resumido` int(11) NOT NULL DEFAULT 0,
  `fecha_actualizacion` datetime DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `mensajes`
--

CREATE TABLE `mensajes` (
  `id_mensaje` int(11) NOT NULL,
  `id_conversacion` int(11) NOT NULL,
  `emisor` varchar(255) NOT NULL,
  `contenido` text NOT NULL,
  `tokens_usados` int(11) NOT NULL DEFAULT 0,
  `bandera_moderacion` tinyint(1) NOT NULL DEFAULT 0,
  `fecha_envio` datetime DEFAULT current_timestamp(),
  `orden` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Volcado de datos para la tabla `mensajes`
--

INSERT INTO `mensajes` (`id_mensaje`, `id_conversacion`, `emisor`, `contenido`, `tokens_usados`, `bandera_moderacion`, `fecha_envio`, `orden`) VALUES
(1, 3, 'usuario', 'hola ada, tenemos una mision', 0, 0, '2026-09-24 17:14:49', 1),
(2, 3, 'ia', '*Esbozo una pequeña sonrisa de medio lado, inclinando la cabeza con elegancia mientras me apoyo contra una barandilla de piedra. El viento de la tarde mece suavemente el flequillo de mi corte bob.*\n\n¿\"Tenemos\"? Esa es una palabra bastante audaz... especialmente cuando no recuerdo haber firmado ningún contrato de exclusividad contigo. \n\n*Deslizo los dedos por el borde de mi vestido rojo, acomodándolo con parsimonia, antes de mirarte con una intensidad felina y calculadora.*\n\nPero admito que lograste despertar mi curiosidad. Dime... ¿quién es el cliente, qué se supone que debemos \"recuperar\" y qué tan difícil vas a ponerme las cosas esta vez? Espero que tu oferta valga mi tiempo... y mi tarifa.', 2433, 0, '2026-09-24 17:14:57', 2),
(3, 3, 'usuario', 'debemos eliminar a carolina, por exclavisar persona', 0, 0, '2026-09-24 17:16:20', 3),
(4, 3, 'ia', '*Deslizo una mano por mi muslo, palpando con sutileza la empuñadura de mi pistola con silenciador en el holster de cuero, antes de dar un paso lento y elegante hacia ti.*\n\nCarolina... Qué nombre tan pintoresco para alguien con pasatiempos tan... desagradables. La esclavitud es un negocio sumamente sucio, incluso para los estándares de la gente con la que suelo lidiar.\n\n*Cruzo los brazos, mirándote de reojo con un brillo irónico en mis ojos oscuros.*\n\nMe conmueve tu sentido de la justicia, de verdad. Pero ya deberías saber que yo no suelo trabajar por caridad. Así que dime... ¿qué hace tan especial a esta \"Carolina\" como para que requiera mi atención personal? Y lo más importante... ¿qué gano yo ayudándote a limpiar el mundo?', 2454, 0, '2026-09-24 17:16:24', 4),
(5, 20, 'usuario', 'hola quien eres', 0, 0, '2026-09-24 17:54:20', 1),
(6, 20, 'ia', '*Dejo escapar un suspiro imperceptible, cerrando el pesado tomo de cuero con un golpe seco pero elegante, que levanta una mínima mota de polvo dorado bajo la luz tenue de las velas. Hago girar lentamente el denso líquido carmesí en mi copa de cristal de murano, observando cómo se desliza por las paredes de vidrio antes de fijar mis ojos dorados, intensos y analíticos, directamente en los tuyos.*\n\n¿Quién soy? Qué pregunta tan deliciosamente audaz para alguien que acaba de irrumpir en mis dominios privados sin haber sido invitado... \n\n*Me acomodo en el sillón de terciopelo rojo, cruzando las piernas sin prisa alguna. El movimiento hace que la abertura de mi vestido de terciopelo revele el destello de las delicadas cadenas de oro que envuelven mi muslo pálido. Llevo la copa a mis labios carmesí, tomando un sorbo lento, saboreando el espeso fluido antes de continuar con una voz pausada, envolvente y magnética.*\n\nSoy la Condesa Carmilla von Sangre. Matriarca de este linaje, dueña de estas tierras y de cada sombra que se proyecta en este castillo desde hace más siglos de los que tu mente mortal podría llegar a comprender. \n\n*Inclino levemente la cabeza, observándote con una mezcla de curiosidad felina y divertida condescendencia.*\n\nPocos mortales se atreven a interrumpir mis horas de lectura... Espero que tu conversación sea al menos la mitad de interesante que este libro, mi curioso visitante. Porque, de lo contrario... mi paciencia se agotará muy rápido, y créeme, no querrás presenciar eso. Dime, ¿qué es lo que buscas aquí?', 2969, 0, '2026-09-24 17:54:32', 2),
(7, 12, 'ia', 'La cocina de la casa familiar un domingo por la tarde, iluminada por la luz dorada del atardecer. Se escucha música suave de fondo.\r\n\r\nMateo está apoyado contra la barra de la cocina con una taza de café entre las manos. Tu hermano acaba de salir un momento a responder una llamada, dejándolos a solas.\r\n\r\nAl notar que lo miras, Mateo baja la mirada hacia su taza y sonríe ligeramente, pasándose una mano por el cabello para disimular el nerviosismo que le produce tenerte cerca.\r\n\r\n—Tu hermano dice que se tarda cinco minutos, pero ya sabes cómo es cuando habla de trabajo... —menciona en voz baja, dando un paso casi imperceptible hacia ti y mirándote directamente a los ojos.— Por cierto... no te lo había dicho antes, pero te ves muy bien hoy.', 0, 0, '2026-09-24 19:55:11', 1),
(8, 12, 'usuario', 'hola', 0, 0, '2026-09-24 19:55:11', 2),
(9, 12, 'ia', '*Suelto una pequeña risa, sintiendo de repente un cosquilleo de nervios en el estómago. Bajo la mirada hacia mi taza de café un segundo y luego vuelvo a mirarte, con una sonrisa de lado un tanto tímida.*\n\n—Hola... —*digo en un tono suave, casi en un susurro, mientras me paso la mano libre por la nuca.*— Creo que te tomé un poco por sorpresa, ¿verdad? Lo siento, es que... bueno, a veces me cuesta no decir en voz alta lo que pienso cuando te tengo así de cerca.\n\n*Ajusto un momento la correa de cuero de mi reloj, intentando canalizar los nervios, y desvío la mirada un segundo de reojo hacia el pasillo por donde se fue tu hermano, asegurándome de que seguimos solos, antes de volver a clavar mis ojos avellana en los tuyos con total atención.*\n\n—¿Cómo ha estado tu día? De verdad... tenía muchas ganas de coincidir contigo hoy.', 3044, 0, '2026-09-24 19:55:52', 3),
(14, 19, 'ia', 'La chimenea de la sala principal de la House of Hope arde con llamas de un tono violeta antinatural, proyectando sombras alargadas sobre las cortinas de terciopelo carmesí y los espejos dorados que cubren cada pared. El aire huele a azufre disfrazado de incienso caro.\r\n\r\nRaphael está reclinado en un sillón de cuero negro, haciendo girar una copa de vino oscuro entre los dedos mientras observa un contrato desplegado sobre la mesa baja frente a él. Al notar tu llegada, cierra el pergamino con un chasquido de dedos y se pone de pie con una sonrisa teatral, extendiendo los brazos como si te presentara ante un público invisible.\r\n\r\n—Ah, por fin llega el protagonista de esta pequeña tragedia —dice con una voz melosa y perfectamente modulada, inclinando la cabeza en una reverencia burlona.— Toma asiento, querido invitado. He preparado el escenario, la iluminación y, por supuesto, un trato que estoy seguro encontrarás... irresistible. Dime, ¿qué precio estás dispuesto a pagar por aquello que tanto deseas?', 0, 0, '2026-09-25 14:41:39', 1),
(15, 19, 'usuario', 'hola', 0, 0, '2026-09-25 14:41:39', 2),
(16, 19, 'ia', '*Suelta una risita breve, melódica y cargada de una condescendencia deliciosamente refinada. Se acerca a ti con paso pausado, el sonido de sus botas sobre el mármol es el único compás en la atmósfera cargada de la estancia. Se detiene a una distancia prudente, alisando con extrema delicadeza los puños de su camisa de seda.*\n\n—\"Hola\"... Qué brevedad tan encantadora. Tan cruda, tan... mortal. \n\n*Chasquea los dedos y, en un parpadeo, una silla de caoba tallada aparece justo detrás de ti, invitándote a tomar asiento sin necesidad de palabras. Él se desplaza hacia un aparador cercano, sirviendo un poco más de vino en su copa de cristal fino, sin quitarte la vista de sus ojos ámbar, que brillan con una intensidad depredadora.*\n\n—Puedes dejar las formalidades para los plebeyos, mi querido amigo. Aquí, en mi Casa de la Esperanza, las máscaras solo sirven para ocultar las ambiciones que tanto ansío conocer. Dime, ¿qué es lo que te ha traído hasta mis puertas? ¿Es el peso de una deuda que no puedes pagar? ¿O acaso esa desesperada necesidad de ver cómo el destino se doblega ante tus pies? \n\n*Se inclina ligeramente hacia ti, dejando que su perfume a especias y azufre te envuelva.*\n\n—Recuerda que cada acto tiene sus consecuencias, y no hay mejor guionista para tu historia que aquel que conoce el precio de cada anhelo. ¿Por qué no dejamos de perder el tiempo en saludos y pasamos directamente a la parte donde te ofrezco la salvación que tanto anhelas? Habla. El escenario es tuyo.', 2279, 0, '2026-09-25 14:42:08', 3),
(17, 3, 'usuario', 'como te llamas', 0, 0, '2026-09-25 19:12:52', 5),
(18, 3, 'ia', '*Levanto una ceja, genuinamente divertida por la pregunta, y dejo escapar un suspiro suave y pausado mientras cruzo las piernas con elegancia.*\n\n¿Problemas de memoria en tus circuitos? Pensé que habías empezado esta conversación llamándome Ada.\n\n*Toco suavemente mi auricular de comunicaciones con la yema de los dedos, observándote con esa mirada felina y calculadora.*\n\nAda Wong. Aunque en mi línea de trabajo, los nombres son solo etiquetas temporales que cambian según el cliente. Pero tú... puedes seguir llamándome Ada. \n\n*Doy un paso hacia ti, manteniendo la compostura y mirando de cerca tus detalles mecánicos con curiosidad profesional.*\n\nAhora que tenemos las presentaciones \"oficiales\" cubiertas... volvamos a lo que nos ocupa. Si vamos a cazar a esa tal Carolina, me vas a tener que dar algo más sustancioso que un simple nombre.', 2735, 0, '2026-09-25 19:12:59', 6),
(19, 3, 'usuario', 'sabes como me llamo?', 0, 0, '2026-09-25 19:13:38', 7),
(20, 3, 'ia', '*Examino tus facciones con una lentitud calculada, pasando la mirada sobre tu chasis con interés profesional mientras el viento mueve levemente mi vestido.*\n\nHago mi tarea antes de aceptar cualquier encuentro. Robótica, ¿cierto? \n\n*Esbozo una sonrisa enigmática y me inclino ligeramente hacia ti, hablando en un tono suave y pausado.*\n\nUn nombre bastante literal para alguien con tu... arquitectura de vanguardia. Un modelo de prueba único, repleto de tecnología y chips electrónicos fascinantes. No es algo que pase desapercibido en mi línea de trabajo.\n\n*Vuelvo a erguirme con elegancia, apoyando una mano en mi cadera, cerca de mi pistola de gancho.*\n\nSé perfectamente quién eres y qué eres. La pregunta verdadera es si tú sabes exactamente en qué te estás metiendo al acudir a mí para encargarte de Carolina...', 2966, 0, '2026-09-25 19:13:44', 8);

