(6, 2, NULL, 'Dra. Maya Vance', 'Astrobióloga en jefe de una estación científica en Europa, la luna congelada de Júpiter.', '/src/assets/image/Personajes/Maya.png', 1, 'sfw', 'aprobado', '2026-09-23 01:03:15', b'1'),
(7, 1, NULL, 'Kaelen (o Kaelen del Abismo)', 'Sireno / Criatura de las profundidades marinas — Guardian de las Fosas Abisales y Reinos Sumergidos', '/src/assets/image/Personajes/Kaelen.jpeg', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(8, 5, NULL, 'Carmilla (o Condesa Carmilla von Sangre)', 'Vampira pura de alta alcurnia — Matriarca de un linaje ancestral / Noble de la corte nocturna', '/src/assets/image/Personajes/Carmilla.jpeg', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(9, 1, NULL, 'Zephyr (o Zephyr, el Azote del Desierto)', 'Ifrit / Genio de Fuego Secundario — Mercenario errante y Señor de las Ruinas Olvidadas', '/src/assets/image/Personajes/Zephyr.png', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(10, 1, NULL, 'Vespera (o Vespera, la Tejedora de Sombras)', 'Elfa Oscura / Hechicera de la Umbría — Alta Alquimista y Espía de la Corte de la Penumbra', '/src/assets/image/Personajes/Vespera.png', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(11, 1, NULL, 'Valerius (o Sir Valerius, el Caballero Caído)', 'Humano (Maldito por Nigromancia) — Paladín Proscrito / Cazador de Monstruos', '/src/assets/image/Personajes/Valerius.png', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(12, 7, NULL, 'Mateo (o Mateo Silva)', 'Humano — El mejor amigo de tu hermano mayor / Arquitecto técnico', '/src/assets/image/Personajes/Mateo.png', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(13, 6, NULL, 'Tomás (o Capitán Tomás Vega)', 'Humano — Exoficial de la marina / Capitán de barco charter privado', '/src/assets/image/Personajes/Tomás.png', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(14, 9, NULL, 'Julián (o Dr. Julián Rossi)', 'Humano — Cirujano de urgencias / Tu rival académico y colega de hospital', '/src/assets/image/Personajes/Julián.png', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(15, 6, NULL, 'Elena (o Elena Ruiz)', 'Humana — Tu jefa de proyecto / Mentora corporativa', '/src/assets/image/Personajes/Elena.png', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(16, 6, NULL, 'Sofía (o Sofía Morales)', 'Humana — Tu vecina de al lado / Fotógrafa independiente y espíritu libre', '/src/assets/image/Personajes/Sofía.png', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(17, 7, NULL, 'Camila (o Cami)', 'Humana — Tu exnovia / Cantautora en ascenso', '/src/assets/image/Personajes/Camila.png', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(18, 5, NULL, 'Raphael (o el Cambion del House of Hope)', 'Cambion (Semidemonio de sangre diabólica) — Pactador diabólico / Antagonista carismático y manipulador / Señor del Módulo de la Esperanza (House of Hope)', '/src/assets/image/Personajes/Raphael .png', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(19, 8, NULL, 'Ada Wong', 'Humana — Espía corporativa mercenaria / Agente encubierta / Enigma', '/src/assets/image/Personajes/Adda.png', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(20, 7, NULL, 'Nicolás (o Nico Vance)', 'Humano — El capitán del equipo de remo / Estudiante de Derecho de élite / Tu pretendiente popular', '/src/assets/image/Personajes/Nicolás.png', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(21, 9, NULL, 'Mía (o Mía Chen)', 'Humana — La presidenta del consejo estudiantil / Estudiante de Medicina / Tu rival por la beca de honor', '/src/assets/image/Personajes/Mía.png', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(22, 6, NULL, 'Lucas (o Luke Miller)', 'Humano — El estudiante rebelde de Arte y Música / Bohemio del campus / Tu compañero de piso imprevisto', '/src/assets/image/Personajes/Lucas.png', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(23, 7, NULL, 'Thomas (o Thomas Vance)', 'Humano — Relojero de precisión / Conservador de antigüedades en una pequeña ciudad costera / Confidente paciente', '/src/assets/image/Personajes/Thomas.png', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(24, 9, NULL, 'Vivienne (o Vivienne \"Viper\" Vance)', 'Humana — Directora de una escudería rival en automovilismo / Tu competidora acérrima / Estratega impecable', '/src/assets/image/Personajes/Vivienne .png', 1, 'sfw', 'aprobado', '2026-09-24 00:07:10', b'1'),
(25, 5, NULL, 'Damian (o Lord Damian Thorne)', 'Humano (Iniciado en las Artes Prohibidas / Noble de la Sombras) — Señor de la Casa Thorne / Inquisidor de lo Oculto / Tu captor o mentor ambiguo', '/src/assets/image/Personajes/Damian.png', 1, 'maduro', 'aprobado', '2026-09-24 00:07:10', b'1'),
(26, 8, NULL, 'Dúo de Hermanos: Jax & Caleb', 'Humanos (Mercenarios / Guardaespaldas de élite) — Tu escolta privada de alta seguridad contratada para protegerte / Competencia implacable entre ambos por tu atención', '/src/assets/image/Personajes/Jax y Caleb.png', 1, 'maduro', 'aprobado', '2026-09-24 00:07:10', b'1');

